sys_script_client.script:
function onLoad() {
    var hr_service = g_form.getValue('hr_service');

    if (hr_service === '11d78aa31bb201509fde86acdd4bcb0b') { // if hr service is h&v
        var case_id = g_form.getUniqueValue().toString();

        var ga = new GlideAjax("x_hccc_hoc_ohs.HoCOHSMUtils");
        ga.addParam("sysparm_name", "getHVAttachmentIconPermissions");
        ga.addParam("sysparm_case_id", case_id);
        ga.getXMLAnswer(getAttachmentPermission);
    }

    function getAttachmentPermission(response) {
        var result = JSON.parse(response); //transform the JSON string to an object

        if (result.hv_attachment_permission === false) {
            //g_form.addInfoMessage("blocking attachment permissions");

            g_form.disableAttachments(); //hides paperclip icon 
        }
    }
}
